/** A renderable plate: JPEG fallback plus optional modern-format variants. */
export interface PlateSource {
  src: string;
  webp?: string;
  avif?: string;
}

/** Normalise legacy bare-URL values (remote registry URLs, user input) into a PlateSource. */
export const asPlate = (plate: PlateSource | string | undefined | null): PlateSource =>
  typeof plate === 'object' && plate !== null ? plate : { src: plate || '' };

export const PLATE = {
  contact: { src: pageContact, webp: pageContactWebp, avif: pageContactAvif },
  api: { src: pageApi, webp: pageApiWebp, avif: pageApiAvif },
  pricing: { src: pagePricing, webp: pagePricingWebp, avif: pagePricingAvif },
  security: { src: pageSecurity, webp: pageSecurityWebp, avif: pageSecurityAvif },
  products: { src: pageProducts, webp: pageProductsWebp, avif: pageProductsAvif },
  methodology: { src: pageMethodology, webp: pageMethodologyWebp, avif: pageMethodologyAvif },
  blogPerformance: { src: pageBlogPerformance, webp: pageBlogPerformanceWebp, avif: pageBlogPerformanceAvif },
  aboutHero: { src: aboutHero, webp: aboutHeroWebp, avif: aboutHeroAvif },
  heroNetwork: { src: heroNetwork, webp: heroNetworkWebp, avif: heroNetworkAvif },
  catalystBg2: { src: catalystBg2, webp: catalystBg2Webp, avif: catalystBg2Avif },
  llmo: { src: llmoPlate, webp: llmoPlateWebp, avif: llmoPlateAvif },
  productStudio: { src: productStudio, webp: productStudioWebp, avif: productStudioAvif },
} satisfies Record<string, PlateSource>;

export type PlateId = keyof typeof PLATE;
